llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the closest retinoid analogue, has a systemic bioavailability of 40% in patients, supporting F ≥ 20% for the retinoid backbone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Tretinoin (ATRA) oral bioavailability is approximately 50% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Even the lower quantitative estimate for oral ATRA bioavailability is 25–30% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Acitretin, an aromatic retinoid, has an absolute oral bioavailability of about 60% (range 36–95%) when given with food, supporting high F for lipophilic retinoid structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, the ethyl ester of acitretin, has an absolute oral bioavailability of about 40% in healthy volunteers, again above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has high absolute oral bioavailability (87%), indicating the phenolic amide head group is not inherently a low-F liability, though its small size limits direct transfer.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest retinoid analogues consistently show oral bioavailability values of 25–72%, all above the 20% threshold. The query's p-hydroxyanilide amide is compatible with high bioavailability based on paracetamol, and although very high lipophilicity and poor solubility are concerns, the consistent retinoid evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide (4-HPR) in humans or animals.",
    "Quantitative impact of first-pass glucuronidation or sulfation of the phenol group on systemic F is unknown.",
    "Food effect and formulation dependence for this specific retinamide are not directly captured.",
    "Some records appear mismatched to their SMILES (e.g., C35, C31) and were not used as threshold-relevant evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

